import { expect, test } from 'bun:test';

import { guard } from '../src/payments/guard';

test('rejects a refund larger than the remaining amount', () => {
  expect(() => guard({ amountMinor: 5000, remainingMinor: 4000 })).toThrow(
    'refund exceeds the remaining refundable amount',
  );
});
